from common import *
R = 'f2-backend'
T = []

# ---------------------------------------------------------------- 351 capacity for one service
T.append(topic(351, 'capacity-planning-for-a-service', R, 21, 'Capacity Planning for One Service',
 ['Turn daily users and per-user actions into peak read and write rates',
  'Estimate storage growth and the RAM needed for a hot set',
  'Decide which number drives the design: reads, writes, storage or memory'],
 2, 12, [221],
 [text(351, 1, 'Four numbers decide most designs',
   'Before choosing a database or a cache, estimate four things for the service: peak reads per second, peak writes per second, how fast stored data grows, and how much of it is hot enough to keep in memory. Each one points at a different bottleneck, and the largest one shapes the design.',
   ['capacity-inputs']),
  text(351, 2, 'Worked example: a feed service at 10M daily users',
   'Each user reads 40 items and posts 2 a day, 1 KB per post. Reads: 10M × 40 = 400M a day, about 4,600 per second on average and about 14K at a 3x peak. Writes: 10M × 2 = 20M a day, about 230 per second and about 700 at peak. Storage grows 20 GB a day, about 7.3 TB a year. If the last 7 days are hot, that is 140 GB of hot data.',
   ['read-write-ratio', 'hot-set']),
  diagram(351, 3, 'From users to resources', 'Every estimate is a chain of multiplications with stated assumptions.', ['capacity-inputs'],
   ['Daily active users × actions per user = actions per day',
    'Actions per day ÷ 86,400 = average per second; × peak factor = peak',
    'Writes per day × bytes per write = storage growth per day',
    'Growth per day × hot days = memory for the hot set',
    'Compare each result with what one node can handle']),
  text(351, 4, 'The read:write ratio picks the tools',
   'A 20:1 read-heavy service benefits from caches and read replicas. A write-heavy service, such as event ingestion, needs cheap appends, partitioning and batching instead; a cache does little for data that is written once and rarely read again.',
   ['read-write-ratio']),
  text(351, 5, 'Trap: sizing memory for all the data',
   'Holding every byte ever written in RAM is rarely needed. Most requests touch recent or popular data. Size the cache for the hot set, measure the hit rate, and let older data live on disk.',
   ['hot-set'])],
 [mc('t351-a1', 'read-write-ratio', 'A service gets 50 reads for every write. Which change usually helps its peak load the most?',
   [('a', 'A cache in front of the reads'), ('b', 'Faster disks for the write path'), ('c', 'Larger write batches from clients'), ('d', 'More partitions for the write log')], 'a',
   'With reads dominating, serving them from memory removes most of the load.'),
  mc('t351-a2', 'capacity-inputs', 'Why multiply the daily average by a peak factor?',
   [('a', 'Daily averages already include the busiest hour'), ('b', 'Traffic bunches into busy hours, and capacity must cover them'), ('c', 'It converts the daily request count into bytes needed for storage'), ('d', 'It accounts for the size of each response')], 'b',
   'Users are not spread evenly over 24 hours; the evening peak can be several times the average.'),
  mc('t351-a3', 'hot-set', 'A service stores 7 TB but 90% of reads hit posts from the last week (140 GB). What should the cache be sized for?',
   [('a', 'All 7 TB, so no read misses'), ('b', 'The 140 GB hot set, then measure the hit rate'), ('c', 'A fixed 1 GB, since caches should stay very small'), ('d', 'Half of the total data, as a safe middle')], 'b',
   'Size for the working set; the long tail of old data can stay on disk.'),
  mc('t351-a4', 'read-write-ratio', 'An ingestion service writes 50K events per second and they are read once, by a nightly job. What matters most?',
   [('a', 'A large read cache in front of the event store'), ('b', 'Read replicas in more regions for the nightly job'), ('c', 'Cheap appends, batching and partitioned storage'), ('d', 'Keeping all events in RAM until the job runs')], 'c',
   'Write-once, read-rarely data is limited by write throughput and storage, not reads.'),
  order('t351-a5', 'capacity-inputs', 'Order the steps of a capacity estimate.',
   ['State users and actions per user', 'Compute daily volume, then per second', 'Apply a peak factor', 'Compute storage growth and the hot set', 'Compare with per-node limits'],
   ['s3', 's5', 's1', 's4', 's2'], 'Inputs, volume, peak, data size, then the comparison that decides the design.'),
  est('t351-a6', 'capacity-inputs', 'A feed has 10M people reading 40 posts apiece each day. Spread across the day, how many reads per second is that?', 'reads/s', 4630,
   ['Reads are spread over 86,400 seconds'], '10M × 40 ÷ 86,400', '400M ÷ 86,400 ≈ 4,630 reads/s',
   'Sanity check: at a 3x peak that is about 14K reads/s, a load a cache handles easily but a single database would feel.', 0.15, [400000, 46300])],
 flash(351, [('Four capacity numbers?', 'Peak reads/s, peak writes/s, storage growth, hot-set memory.'),
             ('Per-second from per-day?', 'Divide by 86,400 (about 10^5), then apply a peak factor.'),
             ('Hot set?', 'The recent or popular data most requests touch; size caches for it, not for all data.')]),
 src([('Google SRE workbook: Managing Load', 'https://sre.google/workbook/managing-load/'),
      ('Redis: Memory optimization', 'https://redis.io/docs/latest/operate/oss_and_stack/management/optimization/memory-optimization/')]),
 deep(['capacity-inputs', 'read-write-ratio', 'hot-set'], 'How a capacity estimate is built',
  ['Start from stated inputs: daily active users, actions per user per day split into reads and writes, the size of each stored item, and how long data is kept. Write them down, because every later number inherits their error, and an interviewer or reviewer can only check what is stated.',
   'Convert daily volume to a rate. A day has 86,400 seconds, about 10^5, so 400M reads a day is about 4,600 per second on average. Traffic is uneven, so multiply by a peak factor taken from real traffic graphs; 2 to 5 times the average is common for consumer services with an evening peak.',
   'Storage growth is writes per day times bytes per write, plus overhead for indexes and replicas. 20M writes of 1 KB is 20 GB a day before replication; with three replicas the disk footprint is 60 GB a day. Over a year that adds up to tens of terabytes, which decides whether one machine or a partitioned store is needed.',
   'Memory follows the access pattern, not the total size. If most reads hit the last week of data, the hot set is a week of writes. Caching it gives a high hit rate; caching more gives diminishing returns. Measure the hit rate after launch and adjust, because popularity curves differ by product.',
   'Finally compare each number with what one node can do, using measured benchmarks for the chosen software and hardware. The largest ratio between demand and single-node capacity is the bottleneck, and the design should address that one first: caching for reads, partitioning for writes or storage, more memory for the hot set.'],
  ['Choosing between a single database and a partitioned store.', 'Sizing caches, replicas and disks before a launch.'],
  ['Avoid precise-looking numbers from guessed inputs; keep one or two significant figures.', 'Avoid planning from averages alone; size for the peak.'],
  ['Number', 'Drives', 'Typical response'],
  [['Peak reads/s', 'Read capacity', 'Caches, read replicas, CDN'],
   ['Peak writes/s', 'Write capacity', 'Batching, partitioning, append-only logs'],
   ['Storage growth', 'Disk and cost', 'Retention limits, tiering, partitioning'],
   ['Hot set', 'Memory', 'Cache size and eviction policy']],
  'The feed service in numbers',
  ['10M daily users, 40 reads and 2 writes each per day', '1 KB per post, 3x peak, the last 7 days are hot'],
  ['Reads: 10M × 40 = 400M a day; 400M ÷ 86,400 ≈ 4,630 per second; about 14K at peak.',
   'Writes: 10M × 2 = 20M a day; about 230 per second; about 700 at peak.',
   'Storage: 20M writes of 1 KB each is 20 GB a day; about 7.3 TB a year before replication.',
   'Hot set: 20 GB × 7 = 140 GB, about three cache nodes with 48 GB usable each.'],
  'Reads dominate and the hot set fits a small cache cluster, so the first design move is a cache in front of a modest database.',
  'Planning from measured load', 'Official documentation',
  'The Google SRE workbook chapter on managing load describes planning capacity from measured demand, keeping headroom for peaks and failures, and load testing to find what one instance can really serve. It also recommends planning for the loss of capacity during failures, so a cluster sized exactly for the peak with nothing spare is not enough once a node or a zone goes down.',
  [('“We have 10 TB, so we need 10 TB of cache.”', '“I’d size the cache for the hot set, about a week of writes here, and check the hit rate.”'),
   ('“Average QPS is 4,600, so one server is fine.”', '“The peak is about three times that, and I’d keep headroom for losing a node.”')],
  ['Estimate peak reads, peak writes, storage growth and the hot set.', 'Divide daily volume by 86,400 and apply a peak factor.', 'The read:write ratio decides between caching and write scaling.', 'Size memory for the hot set, not for all the data.']),
 {"kind": "slider", "title": "Size the feed service", "prompt": "Each user reads 40 items and posts 2 a day at 1 KB; the peak is 3x and the last 7 days are hot. Slide daily active users and watch which number grows past one machine first.",
  "model": "capacity", "params": {"readsPerUser": 40, "writesPerUser": 2, "payloadKb": 1, "peakFactor": 3, "hotDays": 7, "cacheGb": 48},
  "control": {"label": "Daily active users", "min": 1, "max": 100, "step": 1, "initial": 10, "unit": "M"},
  "takeaway": "At 10M users the peak is about 14K reads/s and 694 writes/s, and the 140 GB hot set needs three 48 GB cache nodes. Reads dominate at every size, so caching is the first lever; the hot window decides the memory bill."},
 see([(2, 'The general estimation habits behind these numbers'), (15, 'Where a cache sits once reads dominate')])))

# ---------------------------------------------------------------- 352 storage engines
T.append(topic(352, 'storage-engines-btree-vs-lsm', R, 22, 'Storage Engines: B-trees vs LSM-trees',
 ['Explain how a B-tree updates pages in place and an LSM-tree appends and compacts',
  'Compare write, read and space amplification',
  'Pick an engine for a write-heavy or a read-heavy workload'],
 3, 13, [221],
 [text(352, 1, 'Two ways to keep data sorted on disk',
   'A B-tree keeps sorted data in fixed-size pages and changes a page where it lives. An LSM-tree (log-structured merge-tree) buffers writes in memory, flushes them as new sorted files, and merges those files in the background. Both answer the same queries; they pay for them at different times.',
   ['btree', 'lsm']),
  text(352, 2, 'Worked example: one small update',
   'Changing a 100-byte row in a B-tree rewrites the 8 KB page that holds it, plus a log record: about 8,192 ÷ 100 ≈ 82 bytes written per byte changed, before counting index pages. An LSM-tree appends the new row to its log and memory table at once, but compaction may rewrite it several more times as files are merged level by level.',
   ['amplification']),
  diagram(352, 3, 'The LSM write path', 'Writes are sequential; the cost moves to background merging and to reads.', ['lsm'],
   ['Append the write to a log for durability', 'Insert it into a sorted in-memory table', 'Flush the full table to disk as an immutable sorted file', 'Compaction merges files and drops overwritten or deleted rows', 'Reads check memory, then files from newest to oldest, skipping files by filter']),
  text(352, 4, 'Three kinds of amplification',
   'Write amplification is bytes written to disk per byte the application wrote. Read amplification is how many places a lookup must check. Space amplification is disk used per byte of live data. B-trees usually read less and write more per update; LSM-trees write in large sequential batches, but a read may consult several files and old versions take space until compaction.',
   ['amplification']),
  text(352, 5, 'Trap: “LSM is always faster for writes”',
   'LSM ingestion is cheap at first, but compaction must keep up. If writes outpace merging, files pile up, reads slow down and the engine eventually throttles writers. Measure sustained throughput, not the first minutes of a benchmark.',
   ['lsm', 'amplification'])],
 [mc('t352-a1', 'btree', 'What does a B-tree do when one row in a page changes?',
   [('a', 'Appends the row to a new sorted file and merges it in later compaction'), ('b', 'Rewrites the page that holds the row, after logging the change'), ('c', 'Stores only the changed bytes and nothing else'), ('d', 'Rebuilds the whole index from the table')], 'b',
   'B-trees update pages in place; the write-ahead log makes that safe.'),
  mc('t352-a2', 'lsm', 'Why can an LSM-tree read touch several files?',
   [('a', 'A key may exist in memory and in several sorted files'), ('b', 'Each sorted file stores a single column of the table rows'), ('c', 'Files are stored out of key order'), ('d', 'The engine keeps two copies of each row on disk')], 'a',
   'Newer versions sit in newer files; a lookup checks newest first and filters skip files without the key.'),
  mc('t352-a3', 'amplification', 'An engine writes 30 GB to disk while the application writes 1 GB. What is that?',
   [('a', 'Read amplification of 30'), ('b', 'Space amplification of 30'), ('c', 'Write amplification of 30'), ('d', 'A replication factor of 30')], 'c',
   'Bytes written to disk per byte written by the application.'),
  mc('t352-a4', 'lsm', 'A time-series service ingests many small writes and mostly reads recent ranges. Which engine fits well?',
   [('a', 'An LSM-tree, for cheap sequential ingestion'), ('b', 'A B-tree with a page per row'), ('c', 'Either one, as engines barely differ on write cost'), ('d', 'A hash index, for its range scans')], 'a',
   'High-volume appends suit LSM-trees; hash indexes cannot serve range scans.'),
  order('t352-a5', 'lsm', 'Order the life of a write in an LSM-tree.',
   ['Append to the log', 'Insert into the memory table', 'Flush the table to a sorted file', 'Merge files during compaction'],
   ['s3', 's1', 's4', 's2'], 'Durable first, then in memory, then on disk, then merged.'),
  est('t352-a6', 'amplification', 'A 100-byte row changes in an 8 KB (8,192-byte) page that is written back whole. Roughly what is the write amplification?', 'x', 82,
   ['Only the data page is counted, not the log or index pages'], '8,192 ÷ 100', '8,192 ÷ 100 ≈ 82',
   'Sanity check: small random updates are where B-trees pay most; the log and index pages add more on top.', 0.1, [100, 8])],
 flash(352, [('B-tree update?', 'Rewrite the page in place, after logging the change.'),
             ('LSM write?', 'Log, memory table, flush to sorted file, merge later by compaction.'),
             ('Three amplifications?', 'Write: disk bytes per app byte. Read: places checked. Space: disk per live byte.')]),
 src([('PostgreSQL: Database page layout', 'https://www.postgresql.org/docs/current/storage-page-layout.html'),
      ('Apache Cassandra: Compaction overview', 'https://cassandra.apache.org/doc/latest/cassandra/managing/operating/compaction/overview.html')]),
 deep(['btree', 'lsm', 'amplification'], 'How the two engines spend their I/O',
  ['A B-tree stores rows or keys in fixed-size pages, often 8 KB or 16 KB, arranged as a shallow tree. A lookup reads one page per level, usually three or four, and the top levels stay in memory. An update finds the page, changes it in memory, logs the change, and later writes the whole page back.',
   'Writing whole pages for small changes is the B-tree’s write amplification. Random updates across a large table touch different pages, so the disk sees scattered page writes. In exchange, a read finds the single current version of a row in one place.',
   'An LSM-tree turns writes into sequential appends. Each write goes to a log and an in-memory sorted table. When the table fills, it is flushed as an immutable sorted file. Deletes are written as markers called tombstones, because files are never edited in place.',
   'Compaction merges files to discard overwritten rows and tombstones and to bound how many files a read must check. Leveled compaction keeps files in levels of growing size and rewrites data each time it moves down a level, trading extra writes for fewer files per read. Other strategies merge less often, writing less but leaving more files and more space used.',
   'Reads in an LSM-tree check the memory table and then files from newest to oldest. Per-file filters, such as Bloom filters, answer “definitely not here” for most files, so a point lookup usually reads one or two. Range scans must merge sorted runs from several files, which costs more than a B-tree range scan.'],
  ['LSM-trees for write-heavy ingestion such as logs, metrics and events.', 'B-trees for read-heavy, update-in-place workloads with many range queries.'],
  ['Avoid judging an LSM engine on a short benchmark before compaction starts.', 'Avoid B-trees for huge append-only streams where random page writes dominate.'],
  ['Engine', 'Writes', 'Reads', 'Space'],
  [['B-tree', 'Page rewrite per update', 'One place per key', 'Some free space in pages'],
   ['LSM, leveled', 'Rewritten at each level', 'Few files per lookup', 'Low, after compaction'],
   ['LSM, tiered', 'Fewer rewrites', 'More files per lookup', 'Higher until merges run']],
  'Small updates in an 8 KB page',
  ['100-byte rows, 8,192-byte pages', '1,000 updates per second spread over a large table'],
  ['Each update dirties one page: 8,192 ÷ 100 ≈ 82 bytes written per byte changed.',
   'At 1,000 updates per second that is up to 1,000 × 8 KB ≈ 8 MB/s of page writes, before the log.',
   'If many updates hit the same hot pages between writes to disk, they share one page write, so the real figure is often lower.',
   'An LSM-tree writes the same 100 KB/s sequentially, then rewrites it during compaction a number of times that depends on its levels.'],
  'Neither engine avoids amplification; they choose where to pay it. Measure with the real access pattern.',
  'What the documentation says', 'Official documentation',
  'The PostgreSQL documentation describes tables and indexes stored as arrays of fixed-size pages, normally 8 kB, with each page holding row pointers and tuples. Apache Cassandra’s documentation describes writes going to a commit log and an in-memory structure, flushed to immutable sorted files, with compaction strategies that trade write amplification against the number of files a read must touch.',
  [('“LSM-trees are faster, full stop.”', '“They make writes sequential; I’d check compaction can keep up and what range reads cost.”'),
   ('“A B-tree update writes only the changed row.”', '“It rewrites the page, so small random updates have high write amplification.”')],
  ['B-trees update pages in place; LSM-trees append and compact.', 'Every engine pays write, read or space amplification somewhere.', 'Compaction must keep pace with ingestion.', 'Choose by workload: write-heavy streams vs read-heavy updates and ranges.']),
 {"kind": "predict", "title": "Which engine for the metrics store?", "prompt": "A service ingests 200K small metric points per second and dashboards read the last hour by time range. Which storage engine suits it better, and why?",
  "choices": [{"id": "a", "label": "An LSM-tree: sequential appends absorb the write rate", "feedback": "Right: ingestion dominates, and recent data stays in few, recent files."},
              {"id": "b", "label": "A B-tree: one page per lookup keeps the reads fast", "feedback": "Reads are cheap either way here; scattered page rewrites at 200K writes/s are the real risk."},
              {"id": "c", "label": "A hash index: constant-time writes and reads", "feedback": "Hash indexes cannot serve the time-range reads the dashboards need."}],
  "correctId": "a",
  "reveal": "With a write rate this high, turning writes into sequential appends matters most. The cost moves to compaction, so plan disk bandwidth for it and keep an eye on the number of files per read."},
 see([(23, 'B-tree and LSM indexes in system design terms'), (264, 'How B-tree and hash indexes serve lookups')])))

# ---------------------------------------------------------------- 353 double booking
T.append(topic(353, 'preventing-double-booking', R, 23, 'Preventing Double Booking',
 ['Spot the check-then-insert race behind double bookings',
  'Compare constraints, row locks, optimistic versions and serializable isolation',
  'Choose a fix that holds under concurrent requests'],
 3, 13, [238],
 [text(353, 1, 'The race in check-then-insert',
   'A booking handler reads “is seat 12A free?”, sees yes, and inserts a booking. Two requests can both read “free” before either inserts, and both succeed. Each request is correct on its own; together they break the rule that a seat has one booking.',
   ['check-then-act']),
  text(353, 2, 'Worked example: two requests, 5 ms apart',
   'At 10:00:00.000 request A checks seat 12A and finds it free. At 10:00:00.005 request B checks and also finds it free, because A has not committed yet. A inserts and commits at .010, B at .015. Under the default read-committed isolation in many databases, nothing stops B; the flight now has two passengers in 12A.',
   ['check-then-act', 'isolation']),
  diagram(353, 3, 'Four ways to make the check stick', 'Each one makes the second request fail or wait instead of double booking.', ['fixes'],
   ['Unique constraint on (flight, seat): the second insert fails', 'Lock the seat row first: the second request waits, then sees it taken', 'Version check: update only if the version is unchanged, else retry', 'Serializable isolation: the database aborts one transaction', 'Turn the failure into a clear “seat just taken” reply']),
  text(353, 4, 'Pessimistic or optimistic',
   'Locking the row before checking (pessimistic) makes contenders wait; it suits hot items with frequent conflicts. An optimistic version check lets everyone proceed and rejects the losers at write time; it suits items where conflicts are rare, and it never holds a lock while a user thinks.',
   ['fixes']),
  text(353, 5, 'Trap: checking in the application only',
   'A check in application code, even inside a transaction, does not stop a concurrent insert under read committed or snapshot isolation. The guarantee must come from the database: a constraint, a lock, a conditional update, or serializable isolation.',
   ['isolation'])],
 [mc('t353-a1', 'check-then-act', 'Two requests both read “seat free” and both insert. What is this?',
   [('a', 'A deadlock between the two transactions'), ('b', 'A check-then-act race'), ('c', 'A dirty read of uncommitted data'), ('d', 'A lost connection during commit')], 'b',
   'The decision was based on a read that another transaction made stale.'),
  mc('t353-a2', 'fixes', 'Which fix makes the second insert fail even if the code forgets to check?',
   [('a', 'Logging every booking attempt'), ('b', 'A cache of the free seats kept in app memory'), ('c', 'Retrying the insert on timeout'), ('d', 'A unique constraint on flight and seat')], 'd',
   'Constraints are enforced by the database for every writer.'),
  mc('t353-a3', 'isolation', 'Under snapshot isolation, two transactions insert different rows after each checked the same rule. What can happen?',
   [('a', 'Both commit and the rule is broken'), ('b', 'The second always waits for the first'), ('c', 'Both are aborted by the database'), ('d', 'The second reads the first one’s insert')], 'a',
   'This is write skew: no row was written twice, so snapshot isolation sees no conflict.'),
  mc('t353-a4', 'fixes', 'Concert tickets: thousands of buyers hit the same few seats in seconds. Which approach fits best?',
   [('a', 'Optimistic versions, since conflicts are rare'), ('b', 'A read-only replica for the seat check'), ('c', 'Locking or a conditional update on the seat row'), ('d', 'Checking seat availability twice in the booking code')], 'c',
   'With frequent conflicts, optimistic retries waste work; a lock or atomic conditional update settles each seat once.'),
  order('t353-a5', 'fixes', 'Order a pessimistic booking transaction.',
   ['Begin the transaction', 'Lock the seat row', 'Check that it is free', 'Insert the booking and commit'],
   ['s3', 's1', 's4', 's2'], 'Lock before the check, so the check stays true until commit.'),
  est('t353-a6', 'check-then-act', 'A hotel has 50 rooms and 49 are booked. Three requests check at the same moment, all see a free room, and all insert with no constraint. How many bookings exist afterwards?', 'bookings', 52,
   ['No locks or constraints', 'Every insert succeeds'], '49 + 3', '49 + 3 = 52 bookings for 50 rooms',
   'Sanity check: the overbooking equals the number of racing requests minus the rooms that were really free.', 0, [50, 51])],
 flash(353, [('Why does check-then-insert double book?', 'Two requests can read “free” before either commits.'),
             ('Write skew?', 'Two transactions read the same rule, write different rows, and both commit.'),
             ('Four fixes?', 'Unique constraint, row lock, version check, serializable isolation.')]),
 src([('PostgreSQL: Transaction isolation', 'https://www.postgresql.org/docs/current/transaction-iso.html'),
      ('PostgreSQL: Explicit locking', 'https://www.postgresql.org/docs/current/explicit-locking.html')]),
 deep(['check-then-act', 'isolation', 'fixes'], 'Why the read does not protect the write',
  ['Most databases default to read committed or snapshot isolation. A transaction sees committed data, but nothing it reads is locked against other writers. When the decision to insert depends on a read, another transaction can change what that read would return before the insert commits.',
   'If both transactions update the same row, the database notices: one waits or fails. Double booking is harder because the two transactions insert different rows. Snapshot isolation, used for repeatable read in several databases, allows this write skew.',
   'A unique constraint turns the business rule into something the database enforces on every insert: only one row per flight and seat. The second insert fails with a constraint error, which the handler turns into “seat just taken”. For overlapping ranges, such as hotel nights, some databases offer exclusion constraints; otherwise model each night as a row.',
   'A row lock, taken by reading the seat or room row “for update” before checking, makes the second transaction wait until the first commits, then re-check. An optimistic alternative is a conditional update: set the seat to booked only where it is still free, or only where its version is unchanged, and treat zero rows updated as a lost race.',
   'Serializable isolation detects that the two transactions could not have run one after the other and aborts one of them. It protects every rule without changing the schema, but the application must retry aborted transactions, and heavy contention increases aborts.'],
  ['Bookings, inventory, unique usernames and any “at most N” rule.', 'Flows where a read decides whether a write is allowed.'],
  ['Avoid relying on an application-level check alone.', 'Avoid holding locks while waiting for a user or a remote call.'],
  ['Fix', 'Contention behaviour', 'Cost'],
  [['Unique constraint', 'Second insert fails fast', 'Needs a rule that fits a key'],
   ['Row lock', 'Contenders wait in turn', 'Lock wait time, deadlock care'],
   ['Version or conditional update', 'Losers retry or report', 'Wasted work under heavy contention'],
   ['Serializable isolation', 'Database aborts one', 'Retry logic, more aborts']],
  'How many bookings slip through',
  ['50 rooms, 49 already booked', '3 requests check at the same moment', 'No constraint or lock'],
  ['All 3 see one free room.', 'All 3 insert: 49 + 3 = 52 bookings.', 'With a unique constraint per room and night, 1 insert succeeds and 2 fail.', 'With a row lock, the 2 later requests wait, re-check and see no free room.'],
  'The overbooking equals the racing requests minus the free rooms; any of the four fixes brings it to zero.',
  'What the PostgreSQL documentation says', 'Official documentation',
  'The PostgreSQL documentation on transaction isolation explains that read committed lets each statement see data committed before it began, and that repeatable read in PostgreSQL uses a snapshot. It describes serialization anomalies such as write skew and states that the serializable level detects them and aborts a transaction, which the application must be prepared to retry.',
  [('“We check availability inside a transaction, so it is safe.”', '“The read is not locked; I’d add a unique constraint or lock the row.”'),
   ('“Optimistic locking is always better.”', '“For a few hot seats with many buyers, I’d lock or use an atomic conditional update.”')],
  ['Check-then-insert races under default isolation.', 'Make the database enforce the rule: constraint, lock, conditional update or serializable.', 'Lock for hot items; use versions when conflicts are rare.', 'Turn the conflict into a clear reply and retry where it makes sense.']),
 {"kind": "tradeoff", "title": "Stop the double booking", "prompt": "A cinema app checks “seat free?” then inserts a booking. During a premiere, 2,000 people click the same 20 seats in the first second. Which change prevents double bookings and handles the rush best?",
  "choices": [{"id": "a", "label": "Retry the insert if it times out", "feedback": "Retries do nothing about two requests that both saw the seat as free."},
              {"id": "b", "label": "Atomic conditional update: book the seat only where it is still free", "feedback": "Right: each seat is taken once, and every loser learns at once that it is gone."},
              {"id": "c", "label": "Optimistic versions with automatic retry until success", "feedback": "It prevents duplicates, but with 100 buyers per seat most retries fail again and add load."}],
  "correctId": "b",
  "reveal": "The fix must live in the database. Under heavy contention, an atomic conditional update or a short row lock settles each seat once; a unique constraint is the safety net that catches any code path that forgets."},
 see([(267, 'The isolation anomalies behind write skew'), (72, 'Optimistic and pessimistic locking compared')])))
